definition.raw:
\label{def:good cone}
 A {\bf good cone} in $\R^n$ is a rational polyhedral cone given by
\begin{equation}
C= \bigcap_{i=1}^{m}\{x\in \R^n: \langle x, v_{i}\rangle \geq 0\},
\end{equation}
where $F_{i}=\{x\in \R^n: \langle x,v_{i} \rangle=0\}$ is a facet of
$C$ and $v_{i}\in \Z^n$ is the inward-pointing primitive normal
vector to $F_{i}$. In addition this cone must satisfy:

(i)For $0<l<n$, each codimension $l$ face $F$ of $C$ is contained in
exactly $l$ facets:
\begin{equation*}
F=F_{i_{1}}\cap F_{i_{2}}\cap\cdots\cap F_{i_{l}};
\end{equation*}
and

(ii) The $\Z$-module generated by $v_{i_{1}},...,v_{i_{l}}$ is a
direct summand of $\Z^n$ of rank $l$.

Let the cone be as in
Example~\ref{ex:symplectic cone combina}:
 \begin{equation}
  C= \bigcap_{i=1}^{m}\{x\in \R^n: \langle x, v_{i}\rangle \geq 0\}
\end{equation}
Define a map
\begin{equation}\label{eq:pi_Z contact}
\pi_{\Z}: \Z^m\rightarrow \Z^n
\end{equation}
by sending the $i^{th}$ standard basis vector $e_{i}$ of $\Z^m$ to
$v_{i}$.

\label{def:I}
Define $\I$ to be the ideal of $\Z[x_{i},x_{2},...,x_{m}]$ or
$\Q[x_{i},x_{2},...,x_{m}]$ generated by monomials
\begin{equation*}\left\{x_{i_{1}}x_{i_{2}}\cdots x_{i_{l}}:
\bigcap_{j=1}^{l}\widetilde{F_{i_{j}}}=\emptyset\right\}.\end{equation*}
The coefficients used will be clear in context.

Suppose $\tilde{v_{j}}=(v_{j1},v_{j2},...,v_{jk})$, for $1\leq j\leq
m$. Let
\begin{equation}J_{i}=\sum_{j=1}^{m}v_{ji}x_{j},
\end{equation}
for $1\leq i\leq k$. We define
\begin{equation}
\J=\langle J_{1},J_{2},...,J_{k}\rangle
\end{equation}
to be the ideal in $\Q[x_{1},x_{2},...,x_{m}]$ generated by the
linear terms $\{J_{1},J_{2},...,J_{k}\}$.

\label{def:H_e}
Define the even part of $H^{*}(M;\Z)$ as
\begin{equation}H^{even}(M;\Z)=: \{\alpha\in H^{k}(M;\Z): k \ is\  an\
even\ integer\}.\end{equation}
 Define the odd part of $H^{*}(M;\Z)$ as
\begin{equation}H^{odd}(M;\Z)=: \{\alpha\in H^{k}(M;\Z): k\  is\  an\
odd\ integer\}.\end{equation}

We define linear forms
\begin{equation}
J_{k}=\sum_{i=1}^{m}v_{ik}x_{i}, 1\leq k\leq n,
\end{equation}
and the ideals
\begin{equation}
\J = \langle J_{1},\cdots,J_{n-1},J_{n}\rangle
\end{equation}
and
\begin{equation}
\widetilde{\J}=\langle J_{1},\cdots,J_{n-1}\rangle,
\end{equation}
where $\langle S \rangle$ denotes the ideal in $\Z[x_{1},...,x_{m}]$
generated by the elements of $S$.

