\cite{DJ}\label{thm:symp orbi equi cohomology}
Taking cohomology of diagram~\eqref{eq:diagram sym orb} allows us to
compute the equivariant cohomology of the symplectic toric manifold
\begin{equation}
H_{T^k}^{*}(N;\Z)=H^{*}(ET^k\times_{T^k}(T^k\times
P)/\tilde{\Delta});\Z)= \Z[x_{1},x_{2},...,x_{m}]/\I\ ,
\end{equation}
where $x_{i}\in H_{T^k}^{2}(N;\Z)$, $1\leq i\leq m$, are images of
generators of $H^{*}(ET^m\times_{T^m}pt, \Z)$. And the ideal $\I$
was defined in Definition~\ref{def:I}.

\cite{DJ}\label{thm:symp orbi cohomology}
Taking cohomology of diagram~\eqref{eq:diagram sym orb} allows us to
compute the singular cohomology of symplectic toric manifold.
\begin{equation}
H^{*}(N;\Z)=\Z[x_{1},x_{2},...,x_{m}]/\langle \I,\J\rangle ,
\end{equation}
where $x_{i}\in H^{2}(N;\Z)$, for $1\leq i\leq m$.

\label{thm:contact cohomology}
Assume \begin{equation}
 C= \bigcap_{i=1}^{m}\{x\in \R^n: \langle x, v_{i}\rangle \geq 0\}
\end{equation} is a strictly convex good cone and $M$ is the good contact toric
manifold associated with it. Further assume that
$C_{0}=C\backslash\{\vec{0}\}\subset U\R^n$ and the smoothness
criterion for $C$ holds. Let
\begin{equation}\rho:\frac{\Z[x_{1},...,x_{m}]}{\langle \mathcal
{I},\widetilde{\J} \rangle}\rightarrow
\frac{\Z[x_{1},...,x_{m}]}{\langle \mathcal
{I},\widetilde{\J}\rangle}
\end{equation}
be multiplication by $J_{n}$. Then:

\begin{equation}\label{eq:7}
H^{even}(M;\Z)\simeq coker\rho\simeq \Z[x_{1},...,x_{m}]/\langle
\I,\J \rangle\end{equation} as rings, where $x_{i}$ represents a
cohomology class of degree two.

 Moreover,
\begin{equation}\label{eq:8}
H^{odd}(M;\Z)\simeq ker\rho \end{equation} as $(H^{even}(M;\Z)\simeq
coker\rho)$-modules. A homogeneous polynomial of degree $k$
represents a cohomology class of degree $2k+1$ under this
isomorphism.

\label{thm:vanishing odd}Under the same assumption
for  $M$ as in Theorem~\ref{thm:contact cohomology}, we have
\begin{equation}H^{2k+1}(M;\Z)=0
\end{equation}
for $\{k\in \N: 1\leq 2k+1\leq n-1\}$, and
\begin{equation}
H^{2k}(M;\Q)=0
\end{equation}
for $\{k\in \N:n\leq 2k\leq 2n-2\}$.

